// Writes src/routed.gen.ts: every `db`-first export of src/procedure-sources.ts, wrapped by
// `route` so a data-host handle sends the call to the host. Run after adding a repository:
//   node packages/db/scripts/generate-routed.mjs
// The generated file's type check fails the build when a procedure is missing.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const srcDir = fileURLToPath(new URL("../src", import.meta.url));
const DB_FIRST = /^export (?:async )?function (\w+)(?:<[^(]*>)?\(\s*db\b/gm;

function dbFirstNames(file) {
  return [...readFileSync(file, "utf8").matchAll(DB_FIRST)].map((match) => match[1]);
}

function collect(file) {
  const text = readFileSync(file, "utf8");
  const names = [];
  for (const match of text.matchAll(/^export \* from '(\.[^']+)\.js';/gm)) {
    names.push(...dbFirstNames(path.resolve(path.dirname(file), `${match[1]}.ts`)));
  }
  for (const match of text.matchAll(/^export \{([^}]+)\} from '(\.[^']+)\.js';/gm)) {
    const listed = new Set(match[1].split(",").map((name) => name.trim()));
    const source = path.resolve(path.dirname(file), `${match[2]}.ts`);
    names.push(...dbFirstNames(source).filter((name) => listed.has(name)));
  }
  return names;
}

export function renderRouted() {
  const names = [...new Set(collect(path.join(srcDir, "procedure-sources.ts")))].sort();
  return [
    "// Generated by scripts/generate-routed.mjs; do not edit.",
    "// The same names as the repositories: with a data-host handle each call runs in the host.",
    "import { route } from './data-host-handle.js';",
    "import type { ProcedureName } from './procedure-names.js';",
    "import * as procedures from './procedure-sources.js';",
    "",
    "export * from './procedure-sources.js';",
    "",
    ...names.map((name) => `export const ${name} = route('${name}', procedures.${name});`),
    "",
    "export const ROUTED_PROCEDURE_NAMES = [",
    ...names.map((name) => `  '${name}',`),
    "] as const;",
    "",
    "// Fails to compile, naming the procedure, when a `db`-first export is missing here.",
    "type Unrouted = Exclude<ProcedureName, (typeof ROUTED_PROCEDURE_NAMES)[number]>;",
    "const routedCoversEveryProcedure: [Unrouted] extends [never] ? true : Unrouted = true;",
    "void routedCoversEveryProcedure;",
    "",
  ].join("\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const out = path.join(srcDir, "routed.gen.ts");
  writeFileSync(out, renderRouted());
  console.log(`wrote ${out}`);
}
